      <div class="toolbar"><el-select v-model="addKind" aria-label="新增会员权益组件类型" :disabled="!canEdit"><el-option v-for="name in names" :key="name" :label="labels[name]" :value="name" /></el-select><el-button :disabled="!canEdit" @click="add">添加会员权益组件</el-button></div>
      <template v-if="entries.length">
