        <div class="toolbar"><el-button :disabled="!canEdit" @click="move(-1)">上移会员权益组件</el-button><el-button :disabled="!canEdit" @click="move(1)">下移会员权益组件</el-button><el-button :disabled="!canEdit" type="danger" @click="remove">删除当前会员权益组件</el-button></div>
        <template v-if="block && kind">
          <el-form label-position="top" :disabled="!canEdit">
            <div class="fields"><el-form-item label="会员权益组件显示"><el-select :model-value="!flag(block.isHide)" @update:model-value="visible"><el-option label="显示" :value="true" /><el-option label="隐藏并保留配置" :value="false" /></el-select></el-form-item><el-form-item :label="`${labels[kind]}展示风格`"><el-select :model-value="projection.style" @update:model-value="setStyle"><el-option v-for="(label,index) in styles" :key="index" :label="label" :value="index" /></el-select></el-form-item></div>
            <template v-if="kind==='userInfor' || kind==='newVip'"><h4>展示信息</h4><div class="checks"><el-checkbox v-for="(label,index) in checkLabels" :key="index" :model-value="projection.checks.includes(index)" @update:model-value="setCheck(index,$event)">{{label}}</el-checkbox></div></template>
            <template v-if="kind==='ranking'">
