            </template>
            <template v-if="imageKey"><h4>{{kind==='userInfor'?'会员默认头像':'排行榜标题图片'}}</h4><div class="media-field"><img v-if="imagePreview" :src="imagePreview" :alt="kind==='userInfor'?'会员默认头像':'排行榜标题图片'" /><p class="stored">{{imageReference||'未选择图片'}}</p><SeckillActivityImagePicker :disabled="!canChooseMedia" :editor-key="mediaSession.key" :title="kind==='userInfor'?'选择会员默认头像':'选择排行榜标题图片'" @choose="mediaSession.choose" /><el-button :disabled="!canEdit" @click="setImage('')">清空当前组件图片</el-button></div></template>
            <h4>色调与颜色</h4>
            <p class="hint">跟随主题时，品牌色使用主题；自定义色保留供切换后使用。切换风格不会清空其他风格的配置。</p>
