            <template v-for="field in radiusFields" :key="field.key"><h4>{{labels[kind]}}{{field.label}}</h4><div class="fields"><el-form-item :label="`${labels[kind]}${field.label}模式`"><el-select :model-value="flag(read(block,[field.key,'type']))?1:0" @update:model-value="setRadiusType(field.key,$event)"><el-option label="全部圆角" :value="0" /><el-option label="独立四角" :value="1" /></el-select></el-form-item><el-form-item v-if="!flag(read(block,[field.key,'type']))" :label="`${labels[kind]}${field.label}值`"><el-input-number :model-value="number(read(block,[field.key,'val']))" :min="0" :max="Math.max(100,number(read(block,[field.key,'val'])))" @update:model-value="setRadius(field.key,-1,$event)" /></el-form-item><template v-else><el-form-item v-for="(label,index) in corners" :key="index" :label="`${labels[kind]}${field.label}${label}`"><el-input-number :model-value="number(read(block,[field.key,'valList',index,'val']))" :min="0" :max="Math.max(100,number(read(block,[field.key,'valList',index,'val'])))" @update:model-value="setRadius(field.key,index,$event)" /></el-form-item></template></div></template>
          </el-form>
          <el-alert v-if="error" :title="error" type="error" :closable="false" />
          <div class="toolbar"><el-button v-if="kind!=='userInfor'" :disabled="!canEdit || previewLoading" :loading="previewLoading" @click="loadPreview">读取当前公开内容预览</el-button><el-button v-if="imageKey" :disabled="!canEdit || !pageId || !pagePublished || mediaLoading" :loading="mediaLoading" @click="loadSavedMedia">读取已发布组件图片预览</el-button></div>
          <DiyStatePreview :block="block" :previews="previews" :data="previewData" :loaded="previewLoaded" :loading="previewLoading" :error="previewError" />
        </template>
      </template>
      <p v-else class="hint">此页面暂无会员权益组件。可添加普通组件，或继续编辑下方导入 JSON。</p>
    </template>
  </section>
</template>
<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue';
import { useAuthStore } from '@/stores/auth';
import { getToken } from '@/utils/auth';
import SeckillActivityImagePicker from '@/pages/activity/SeckillActivityImagePicker.vue';
import DiyStatePreview from '@/components/content/DiyStatePreview.vue';
import { STATE_NAMES as names, stateLabels as labels, stateKind, stateEntries, stateDocument, stateRecord as record, stateRead as read, stateNumber as number, addStateBlock, moveStateBlock, stateColours, stateChecks, canonicalStateBlock, type StateKind, type StateRecord, type StateColour } from '@/utils/diyStateEditor';
import { normalizeDiyStateWidget, statePreviewTheme, emptyDiyStateData, safeDiyColor } from '@/utils/diyStateProjection';
import { navFlag as flag, navText as text, navSet, canonicalNavigationImage } from '@/utils/diyNavigationEditor';
import { canonicalPresentationReference, presentationPreviewForReference, presentationPreviewUrl } from '@/utils/diyPresentationEditor';
import { apiDiyStatePreview } from '@/api/diyStateAuthor';
const props=withDefaults(defineProps<{modelValue:string;editorKey:string;disabled?:boolean;pageId?:number;pagePublished?:boolean}>(),{disabled:false,pageId:0,pagePublished:false}),emit=defineEmits<{'update:modelValue':[value:string]}>(),auth=useAuthStore();
const selected=ref(-1),addKind=ref<StateKind>('userInfor'),revision=ref(0),error=ref(''),previews=ref<Record<string,string>>({}),previewData=ref(emptyDiyStateData()),previewLoading=ref(false),previewLoaded=ref(false),previewError=ref(''),mediaLoading=ref(false);
let alive=true,lastCommitted='',previewAbort:AbortController|null=null,mediaAbort:AbortController|null=null;
const actor=()=>`${auth.token}:${auth.userInfo?.id}:${auth.userInfo?.level}:${auth.uniqueAuth.join(',')}:${getToken()}:${localStorage.getItem('admin_session')}`;
function editable(){return alive&&!props.disabled&&!!auth.token&&auth.token===getToken()&&!!auth.userInfo&&(auth.userInfo.level===0||auth.uniqueAuth.includes('dise.manage'));}
const canEdit=computed(()=>{void revision.value;return editable();}),canChooseMedia=computed(()=>canEdit.value&&!!auth.userInfo&&(auth.userInfo.level===0||auth.uniqueAuth.includes('attachment.view')));
const parsed=computed(()=>{try{return{value:stateDocument(props.modelValue),error:''};}catch(reason){return{value:null,error:reason instanceof Error?reason.message:'装修JSON无效'};}}),document=computed(()=>parsed.value.value),entries=computed(()=>stateEntries(document.value??[])),block=computed(()=>record(document.value?.[selected.value])),kind=computed(()=>stateKind(block.value?.name)),projection=computed(()=>normalizeDiyStateWidget(block.value,statePreviewTheme));
const styles=computed(()=>kind.value==='userInfor'?['上下展示','左右展示']:kind.value==='newVip'?['经典新人专区','现代新人专区']:kind.value==='signIn'?['每周签到','签到奖励']:['纵向榜单','组合榜单']),checkLabels=computed(()=>kind.value==='userInfor'?['优惠券','积分','余额','会员码','收藏','浏览']:['积分','优惠券','新人商品']);
const tones=computed(()=>[{key:'toneConfig',label:kind.value==='newVip'?'新人积分色调':kind.value==='userInfor'?'进度条色调':'组件色调'},...(kind.value==='newVip'?[{key:'toneCouponConfig',label:'新人优惠券色调'},{key:'toneGoodsConfig',label:'新人商品价格色调'}]:[])]),colours=computed(()=>kind.value?stateColours(kind.value):[]);
const lengths=computed(()=>[...(kind.value==='ranking'?[{key:'titleNumber',label:'标题字号',fallback:16},{key:'bntNumber',label:'更多字号',fallback:12}]:kind.value==='newVip'?[{key:'spacingConfig',label:'经典优惠券间距',fallback:4},{key:'spacingConfig2',label:'现代优惠券间距',fallback:10}]:[]),{key:'topConfig',label:'上边距',fallback:0},{key:'bottomConfig',label:'下边距',fallback:0},{key:'prConfig',label:'左右边距',fallback:0},{key:'mbConfig',label:'组件间距',fallback:0}]);
const radiusFields=computed(()=>[{key:'fillet',label:'模块圆角'},...(kind.value==='ranking'?[{key:'filletBg',label:'榜单圆角（px）'},{key:'filletImg',label:'图片圆角'}]:[])]),corners=computed(()=>kind.value==='userInfor'||kind.value==='signIn'?['左上','右上','右下','左下']:['左上','右上','左下','右下']);
const imageKey=computed(()=>kind.value==='userInfor'?'logoConfig':kind.value==='ranking'?'imgConfig':null),imageReference=computed(()=>imageKey.value?text(read(block.value,[imageKey.value,'url'])):''),imagePreview=computed(()=>presentationPreviewForReference(imageReference.value,previews.value[canonicalPresentationReference(imageReference.value)])||presentationPreviewUrl(imageReference.value));
function stamp(){return{revision:revision.value,actor:actor(),editor:props.editorKey,index:selected.value,raw:props.modelValue};}
function current(s:ReturnType<typeof stamp>){return editable()&&s.revision===revision.value&&s.actor===actor()&&s.editor===props.editorKey&&s.index===selected.value&&s.raw===props.modelValue;}
function invalidate(){error.value='';revision.value++;previewAbort?.abort();mediaAbort?.abort();previewAbort=mediaAbort=null;previewData.value=emptyDiyStateData();previewLoading.value=previewLoaded.value=mediaLoading.value=false;previewError.value='';previews.value={};}
watch(entries,()=>{if(!entries.value.some(row=>row.index===selected.value))selected.value=entries.value[0]?.index??-1;},{immediate:true});
watch(()=>[props.modelValue,props.editorKey,props.disabled,props.pageId,props.pagePublished,actor()],invalidate,{flush:'sync'});
window.addEventListener('admin-session-changed',invalidate);window.addEventListener('admin-auth-expired',invalidate);window.addEventListener('storage',invalidate);
onBeforeUnmount(()=>{alive=false;invalidate();window.removeEventListener('admin-session-changed',invalidate);window.removeEventListener('admin-auth-expired',invalidate);window.removeEventListener('storage',invalidate);});
function commit(value:unknown[]){if(!editable())return false;try{const raw=JSON.stringify(value,null,2);stateDocument(raw);invalidate();lastCommitted=raw;emit('update:modelValue',raw);error.value='';return true;}catch(reason){error.value=reason instanceof Error?reason.message:'无法完整保存';return false;}}
function edit(change:(row:StateRecord)=>boolean|void){if(!editable()||!document.value||!block.value||!kind.value)return false;try{const value=structuredClone(document.value),row=record(value[selected.value]);if(!row)return false;if(change(row)===false)return false;return commit(value);}catch(reason){error.value=reason instanceof Error?reason.message:'当前字段无法修改';return false;}}
function setLeaf(path:Array<string|number>,value:unknown){if(read(block.value,path)===value)return false;return edit(row=>navSet(row,path,value));}
function select(value:unknown){if(typeof value==='number'&&entries.value.some(entry=>entry.index===value)){invalidate();selected.value=value;}}
function add(){if(!document.value)return;try{const result=addStateBlock(document.value,addKind.value);if(commit(result.value))selected.value=result.selected;}catch(reason){error.value=reason instanceof Error?reason.message:'无法添加组件';}}
function remove(){if(!document.value||!kind.value)return;const value=structuredClone(document.value);value.splice(selected.value,1);if(commit(value))selected.value=-1;}
function move(direction:-1|1){if(!document.value)return;try{const result=moveStateBlock(document.value,selected.value,direction);if(commit(result.value))selected.value=result.selected;}catch(reason){error.value=reason instanceof Error?reason.message:'不能移动组件';}}
function visible(value:unknown){if(typeof value==='boolean'&&flag(block.value?.isHide)!==!value)setLeaf(['isHide'],!value);}
function enumNumber(raw:unknown,fallback=0,max=1){const n=Number(raw);return Number.isInteger(n)&&n>=0&&n<=max?n:fallback;}
function setStyle(value:unknown){if(typeof value==='number'&&[0,1].includes(value)&&projection.value.style!==value)setLeaf(['styleConfig','tabVal'],value);}
function setEnum(key:string,value:unknown,max=1){if(typeof value==='number'&&Number.isInteger(value)&&value>=0&&value<=max&&Number(read(block.value,[key,'tabVal']))!==value)setLeaf([key,'tabVal'],value);}
function setText(key:string,value:unknown){if(typeof value==='string'&&!/[\u0000-\u001f\u007f]/u.test(value)&&value.length<=Math.max(6,text(read(block.value,[key,'value'])).length))setLeaf([key,'value'],value);}
function setCheck(id:number,value:unknown){if(typeof value==='boolean')edit(row=>stateChecks(row,id,value));}
function colour(field:StateColour){return safeDiyColor(read(block.value,[field.key,'color',field.index,'item']),field.fallback);}
function setColour(field:StateColour,value:unknown){if(typeof value==='string'&&colours.value.some(f=>f.key===field.key&&f.index===field.index)&&safeDiyColor(value,'')===value.trim())setLeaf([field.key,'color',field.index,'item'],value.trim());}
function setLength(key:string,value:unknown,fallback=0){if(typeof value==='number'&&Number.isFinite(value)&&value>=0&&value<=100&&value!==number(read(block.value,[key,'val']),fallback))setLeaf([key,'val'],value);}
function setRadiusType(key:string,value:unknown){if((value===0||value===1)&&flag(read(block.value,[key,'type']))!==(value===1))setLeaf([key,'type'],value);}
function setRadius(key:string,index:number,value:unknown){const path=index<0?[key,'val']:[key,'valList',index,'val'];if(typeof value==='number'&&Number.isFinite(value)&&value>=0&&value<=100&&value!==number(read(block.value,path)))setLeaf(path,value);}
function setImage(value:string){try{return imageKey.value?setLeaf([imageKey.value,'url'],canonicalNavigationImage(value)):false;}catch(reason){error.value=reason instanceof Error?reason.message:'图片地址无效';return false;}}
const mediaSession=computed(()=>{const issued=stamp(),index=selected.value,key=imageKey.value,owner=actor(),editor=props.editorKey;return{key:`${props.editorKey}:${revision.value}:${index}:${key}`,choose:async(reference:string,signed:string)=>{if(!current(issued)||!canChooseMedia.value)return;const approved=presentationPreviewForReference(reference,signed);if(!approved)return;if(canonicalPresentationReference(imageReference.value)===canonicalPresentationReference(reference)){previews.value={[canonicalPresentationReference(reference)]:approved};return;}if(!setImage(reference))return;const expected=lastCommitted;await nextTick();if(alive&&editable()&&canChooseMedia.value&&actor()===owner&&props.editorKey===editor&&selected.value===index&&imageKey.value===key&&props.modelValue===expected&&canonicalPresentationReference(imageReference.value)===canonicalPresentationReference(reference)&&approved)previews.value={[canonicalPresentationReference(reference)]:approved};}};});
async function loadPreview(){if(!editable()||!kind.value||kind.value==='userInfor')return;previewAbort?.abort();const issued=stamp(),controller=new AbortController(),expected=kind.value;previewAbort=controller;previewData.value=emptyDiyStateData();previewLoading.value=true;previewLoaded.value=false;previewError.value='';try{const value=await apiDiyStatePreview(expected,controller.signal);if(current(issued)&&!controller.signal.aborted){previewData.value=value;previewLoaded.value=true;}}catch(reason){if(current(issued)&&previewAbort===controller&&!controller.signal.aborted)previewError.value=reason instanceof Error?reason.message:'公开预览读取失败';}finally{if(previewAbort===controller){previewAbort=null;previewLoading.value=false;}}}
async function loadSavedMedia(){if(!editable()||!block.value||!imageKey.value||!props.pageId||!props.pagePublished)return;mediaAbort?.abort();const issued=stamp(),id=props.pageId,slot=imageKey.value,expected=JSON.stringify(canonicalStateBlock(block.value)),controller=new AbortController();mediaAbort=controller;mediaLoading.value=true;previews.value={};error.value='';try{const response=await fetch(`/api/diy/get_diy/${id}`,{method:'GET',credentials:'omit',cache:'no-store',signal:controller.signal}),body=record(await response.json()),data=record(body?.data);if(!current(issued)||props.pageId!==id||!props.pagePublished||controller.signal.aborted)return;if(!response.ok||body?.status!==200||!Array.isArray(data?.value))throw Error('公开组件图片暂不可用');const found=data.value.map(record).find(row=>row&&JSON.stringify(canonicalStateBlock(row))===expected);if(!found)throw Error('当前组件与已发布内容不同，请保存后再读取');const approved=presentationPreviewForReference(imageReference.value,read(found,[slot,'url']));if(approved)previews.value={[canonicalPresentationReference(imageReference.value)]:approved};}catch(reason){if(current(issued)&&mediaAbort===controller&&!controller.signal.aborted)error.value=reason instanceof Error?reason.message:'组件图片预览失败';}finally{if(mediaAbort===controller){mediaAbort=null;mediaLoading.value=false;}}}
</script>
<style scoped>
.state-author-editor{width:100%;min-width:0}.hint{font-size:12px;line-height:1.6;color:var(--el-text-color-secondary);margin:6px 0 10px}.toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:10px 0}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 16px}.checks{display:flex;gap:8px;flex-wrap:wrap}.media-field{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px}.media-field img{width:72px;height:48px;object-fit:contain;border:1px solid var(--el-border-color)}.stored{max-width:100%;overflow-wrap:anywhere;font-size:12px;flex-basis:100%;margin:0}.state-author-editor h4{font-size:13px;margin:16px 0 8px}.state-author-editor :deep(.el-select){max-width:100%}.state-author-editor :deep(.el-input-number){width:100%}
